INSERT INTO `posts` VALUES (1, 'ល្អមើលទៀតហើយ! និស្ស័យស្នេហ៍ក្មេងស្រីមេផ្ទះ និងកូនសេដ្ឋី រំលេចបានជាខ្សែភាពយន្តភាគថៃថ្មីចាក់ផ្សាយនៅភីអិនអិន ក្នុងរឿង «ប្រពន្ធក្លែងក្លាយ »', 1, 1, NULL, 'ថ្ងៃទី០៩ ខែតុលា ឆ្នាំ២០២១', 'comingsoon', 'comin', '', 1, '10092021094911616103278b676.jpg', '<p>ទស្សនិកជន ដែលនិយមគាំទ្រទស្សនារឿងភាគថៃថ្មីល្អៗមើល ប្រចាំឲ្យស្ថានីយទូរទស្សន៍ភីអិនអិន នឹងកាន់តែជក់ចិត្តជាមួយនឹងការមកដល់នៃខ្សែភាពយន្តភាគថៃមួយនោះគឺ រឿង&nbsp;<strong>&laquo;ប្រពន្ធក្លែងក្លាយ&raquo;។</strong>&nbsp;ជាសាច់រឿងមួយ ដែលឆ្លុះបញ្ចាំងពីការតស៊ូក្នុងជីវិតការងាររបស់ក្មេងស្រីមួយរូប នៅក្នុងគ្រួសារមានជីវិភាពក្រីក្រ ប៉ុន្តែនាងមានឆន្ទៈ និងការយកចិត្តទុកដាក់ចំពោះការងារនាងខ្លាំងណាស់។&nbsp;</p>\r\n<p><img src=\"../../../assets/images-uploads/CF4KDvHKlWE7p5oJktzagYR8P3FWJIVbY4dNXc8T.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p>តាវ៉ាន់ ជាក្មេងស្រីដ៏ស្រស់ស្អាតរស់នៅក្នុងគ្រួសារដែលមានជីវភាពក្រីក្រ។ &nbsp;ការងាររបស់នាង គឺជាអ្នកអនាម័យតាមអនឡាញ។ ជារៀងរាល់អាទិត្យ ម្តាយរបស់យ៉តហ្វា ដែលជាគ្រួសារអភិជន បានហៅនាងឲ្យមកធ្វើការបោសសម្អាតផ្ទះដ៏ធំរបស់ខ្លួនជាញឹកញាប់។ ពេលវេលាសន្យាបានមកដល់ ម្តាយឪពុករបស់<strong>យតហ្វា&nbsp;</strong>បានបង្ខំឲ្យនាង​រៀបការជាមួយនឹងកូនប្រុសមិត្តសម្លាញ់ គឺ<strong>តូម៉ន</strong>&nbsp;ដែលជាម្ចាស់ក្រុមហ៊ុនរថយន្តដ៏ធំ។</p>\r\n<p><img src=\"../../../assets/images-uploads/4hKqrqKuqbtDBdTwXH943qUQ2kytBErStn62tfrL.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p><img src=\"../../../assets/images-uploads/0NQOYMFFKrZxQ5JX2Guk4UxcJGGoqInen5eGghVa.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p><strong>យ៉តហ្វា</strong>&nbsp;ភ្លើតភ្លើននឹងភាពមានបាន មានសង្សារដើរលេងភ្លេចខ្លួន ក៏មិនពេញចិត្តនឹងការរៀបការនេះដែរ។ នាងបានសុំឲ្យម្តាយរបស់នាង រកកូនក្រមុំមករៀបការជំនួសនាង ដោយអ្នកដែលត្រូវជំនួសនោះ គឺជា តាវ៉ាន់។ តាវ៉ាន់ ដោយសារតែត្រូវការប្រាក់ព្យាបាលម្តាយ នាងសុខចិត្តលះបង់ភាពនៅលីវ ហើយបន្លំខ្លួនធ្វើជាកូនក្រមុំរៀបការជាមួយនឹងតូម៉ន ជំនួសយតហ្វា។</p>\r\n<p><img src=\"../../../assets/images-uploads/Ie9tInUBqPoOTuLjtH17ij2NIjdmikLDczCuRgh6.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p><img src=\"../../../assets/images-uploads/pSKHhYxblE8tjqNi8e8P3tkeOm2vamWdxw1qvX0z.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p>អាពាហ៍ពិពាហ៍ក្លែងក្លាយ បានធ្វើឲ្យតូម៉នចាប់អារម្មណ៍មកលើតាវ៉ាន់ ពីទឹកចិត្ត និងការធ្វើការដោយយកចិត្តទុកដាក់លើនាង ហើយប្រែចិត្តទៅជាស្រឡាញ់គ្នាបន្តិចម្តងៗ។&nbsp;<br /><strong>&laquo;ប្រពន្ធក្លែងក្លាយ&raquo;</strong>&nbsp;ក៏ជាខ្សែភាពយន្តភាគយន្តភាគថ្មីសន្លាង ផលិតនៅក្នុងឆ្នាំ២០២១ ដែលអមទៅដោយវត្តមានតារាសម្តែងស្រស់ស្អាត វ័យក្មេង ជាច្រើននាក់។ ក្នុងនោះ រួមមានដូចជា កញ្ញា&nbsp;<strong>Pie Rinrada Kaewbuasa</strong>i, &nbsp;សម្តែងជាតួអង្គ ( តាវ៉ាន់) , លោក &nbsp;<strong>Mai Warit Sirisantana</strong>&nbsp;សម្តែងជាតួអង្គ ( តូម៉ន) , &nbsp;កញ្ញា&nbsp;<strong>Pear Pitchapa Phanthumchinda</strong>&nbsp;សម្តែងជាតួអង្គ យ៉តហ្វា , អ្នកនាង&nbsp;<strong>Kik Mayurin Pongpudpunth</strong>&nbsp;&nbsp;សម្តែងជាតួអង្គ ( ម្តាយរបស់ យ៉តហ្វា ) , លោក&nbsp;<strong>Toon Hiranyasap&nbsp;</strong>សម្តែងជាតួអង្គ ( ប៉ារបស់ តូម៉ន) និងតារាសម្តែងថៃល្បីៗជាច្រើនរូបទៀត។&nbsp;</p>\r\n<p><img src=\"../../../assets/images-uploads/707BCO0DSO9KauDlnsEveWk3rv3CKhwRErVGJvlQ.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p><img src=\"../../../assets/images-uploads/PdWlQDAFL75Avh1eqkFzjcLZtXPiQLMttCM6yxvK.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p>ដើម្បីចង់ដឹងថា តើខ្សែជិវិតរបស់នាងតូច តាវ៉ាន់ នឹងមានវាសនាបែបណា ហើយតើគេនឹងជួបបញ្ហាអ្វីខ្លះ នៅពេលដែលគេទទួលតំណែងជាកូនក្រមុំក្លែងក្លាយជាមួយនឹងកូនសេដ្ឋីរូបសង្ហារ សូមរង់ចាំទស្សនានៅក្នុងរឿង<strong>&laquo; ប្រពន្ធក្លែងក្លាយ&raquo;</strong>&nbsp;ដែលមានផ្សាយជូននៅលើកញ្ចក់ទូរទស្សន៍<strong>ភីអិនអិន</strong>&nbsp;ចាប់ពីថ្ងៃទី ០៨ ខែ តុលា ឆ្នាំ ២០២១ ពីថ្ងៃចន្ទ ដល់ថ្ងៃសុក្រ វេលាម៉ោង ១១ ព្រឹក៕&nbsp;<br />សូមទស្សនាវីដេអូខ្លីខាងក្រោម៖</p>\r\n<p><iframe style=\"border: none; overflow: hidden;\" src=\"https://www.facebook.com/plugins/video.php?height=314&amp;href=https%3A%2F%2Fwww.facebook.com%2FPNNDramaFanClub%2Fvideos%2F383268646631218%2F&amp;show_text=true&amp;width=560&amp;t=0\" width=\"560\" height=\"429\" frameborder=\"0\" scrolling=\"no\" allowfullscreen=\"allowfullscreen\"></iframe></p>', 1, '2021-10-09 09:49:11', '2021-10-09 09:49:11');
INSERT INTO `posts` VALUES (2, 'តារាចម្រៀង Idol យុវវ័យ លោក Step នឹងមកកាន់ឆាកតន្ត្រី Ganzberg Uber Concert -2021 នារាត្រីថ្ងៃអាទិត្យនេះ', 1, 1, NULL, 'ថ្ងៃទី០៩ ខែតុលា ឆ្នាំ២០២១', '២០:០០-២១:០០', '២០:០០', 'ច័ន្ទ-ពុធ', 1, '100920210957176161050d325f2.jpg', '<p>កម្មវិធីតន្ត្រីបែប Acoustic ដ៏រស់និយមរបស់ស្ថានីយទូរទស្សន៍ភីអិនអិន គឺតន្ត្រី&nbsp;<strong>Ganzberg Uber Concert -2021</strong>&nbsp;នៅតែបម្រើជូនចំណីចក្ខុ អមដោយការប្រគុំនូវតន្ត្រី ចម្រៀងពីរោះ រណ្តំចិត្ត ទៅដល់ទស្សនិកជនទស្សនាកម្សាន្តជារៀងរាល់សប្តាហ៍។ សម្រាប់ការមកដល់នៃឆាកតន្ត្រី នាសប្តាហ៍ថ្មីនេះ ហ្វេនៗ នឹងបានទស្សននាកម្សាន្ត ការបកស្រាយចម្រៀង ពីតារាចម្រៀងប្រុសយុវវ័យ វ័យក្មេងមួយរូប គឺ លោក&nbsp;<strong>Step</strong>&nbsp;។&nbsp;</p>\r\n<p><img src=\"../../../assets/images-uploads/Px9XUE06GYRlGudqFUud7XagMN1MKicJv3tFQ3dk.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p class=\"img-full\">កម្រងបទចម្រៀងមនោសញ្ចេតនា ស្នេហា បែបរ៉ូមែនទិចរបស់លោកជាច្រើនបទ ដែលកំពុងតែទទួលបានការចាប់អារម្មណ៍ និងផ្ទុះខ្លាំង ។ ដូចជា បទ ដាច់ប៉ារ៉ាស ដែលជាបទថ្មី ពេញនិយម សម្រាប់យុវវ័យនាយសម័យបច្ចុប្បន្ន។ មិនថាតែជាប្រភេទបទ slow ឬបទជាទម្រង់ញាក់ ឬ &nbsp;Acoustic ទេ ក៏លោកនៅតែអាចបញ្ចេញនូវទឹកដមសំនៀង យ៉ាងផ្អែម ពីរោះយ៉ាង ជាប់ចិត្ត។&nbsp;<br />ទន្ទឹមគ្នានឹងការបង្ហាញវត្តមានរបស់លោកហើយ វត្តមានតារាស្រីមួយរូបទៀត ដែលជាតារាសម្តែង រាងតូចច្រឡឹង និងក៏ជាម្ចាស់ក្លឹបឋដើរម៉ូតផងនោះ គឺ កញ្ញា<strong>&nbsp;ព្រះកាយ ច័ន្ទ&nbsp;</strong>ក៏នឹងចូលខ្លួនមកបម្រើអារម្មណ៍ទស្សនិកជន តាមរយៈការបកស្រាយចម្រៀងពីរោះៗ អមជាមួយនឹងក្បាច់រាំដ៏ទាក់ទាញទៀតផង។ ក្រៅពីនេះទៀត ពីកម្មវិធី ក៏នឹងបន្ថែមនូវវត្តមាន តារាស្រី៣រូបទៀត រួមមាន កញ្ញា&nbsp;<strong>រី រង្សី</strong>&nbsp;, កញ្ញា&nbsp;<strong>ឡុង រតនា</strong>&nbsp;និងកញ្ញា&nbsp;<strong>ឃន ពិដោរ</strong>។ ពួកគាត់ទាំងបី ក៏ជាតារាសិល្បៈ ដែលមានសមត្ថភាពក្នុងការសម្តែង បកស្រាយចម្រៀង បានយ៉ាងជាប់ចិត្ត ទាំងបទមនោសញ្ចេតនា និងបទញាក់កន្តា្រក់អារម្មណ៍។&nbsp;</p>\r\n<p class=\"img-full\"><img src=\"../../../assets/images-uploads/3iPSg2ONURwQk3K9kQk5oVCAoxSFlIRDt9fnkxUW.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p class=\"img-full\"><img src=\"../../../assets/images-uploads/ETufVvXKdgZWUmfTKiEMOxhtqFJmsYM7NjOfYWbA.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p class=\"img-full\"><img src=\"../../../assets/images-uploads/JE9JOhJ2UZpUlpruJuxcCtnHTqMpEBidpWavXOLB.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p class=\"img-full\"><img src=\"../../../assets/images-uploads/f6WMTkKVYadrNMfXScUkyUI8GF0inogcriNRmN6i.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p class=\"img-full\">ចង់ដឹងថា តើវត្តមានតារាកិត្តិយសខាងលើ នឹងពាំនាំយកនូវអ្វីជាពិសេស បម្រើអារម្មណ៍ទស្សនិកជន មុនចូលនិន្ទ្រានាងចុងសប្តាហ៍ សូមរង់ចាំការផ្សាយផ្ទាល់ក្នុងកម្មវិធីតន្ត្រី&nbsp;<strong>Ganzberg Uber Concert&nbsp;</strong>នៅលើកញ្ចក់ទូរទស្សន៍<strong>ភីអិនអិន</strong>&nbsp;នៅថ្ងៃអាទិត្យ ទី ១០ ខែ តុលា ឆ្នាំ ២០២១ ចាប់ពីវេលាម៉ោង ០៨ យប់តទៅ៕&nbsp;<br />សូមទស្សនាវីដេអូខាងក្រោម៖&nbsp;</p>\r\n<p class=\"img-full\"><iframe style=\"border: none; overflow: hidden;\" src=\"https://www.facebook.com/plugins/video.php?href=https%3A%2F%2Fwww.facebook.com%2FPNNTVCambodia%2Fvideos%2F219500326839916%2F&amp;show_text=0&amp;width=560\" width=\"560\" height=\"315\" frameborder=\"0\" scrolling=\"no\" allowfullscreen=\"allowfullscreen\"></iframe></p>', 1, '2021-10-09 09:57:17', '2021-10-09 09:57:17');
INSERT INTO `posts` VALUES (3, 'កម្សាន្តអារម្មណ៍ក្រោយពិធីបុណ្យភ្ជុំបិណ្ឌ ពីស្រីស្អាត រ៉ាប៊ី ម្ចាស់បទមាន់ស្រែ គ្រលែងអស់ដៃក្នុងកម្មវិធីតន្ត្រី Freshy Happy Concert សប្តាហ៍នេះ', 0, 1, NULL, 'ថ្ងៃទី០៩ ខែតុលា ឆ្នាំ២០២១', '១៨:០០-១៩:០០', '១៨:០០', 'ច័ន្ទ-សុក្រ', 1, '1009202111312761611b1fbb7c5.jpg', '<p>រយៈពេល ៣ ថ្ងៃនៃការឈប់សម្រាកនាពិធីបុណ្យភ្ជុំបិណ្ឌ ប្រពៃណីជាតិ ប្រជាជន ក៏ដូចជាទស្សនិកជនទាំងអស់ ប្រហែលជារង់ចាំនូវការទទួលយកនូវការទស្សនាកម្មវិធីកម្សាន្តនានារបស់ស្ថានីយទូរទស្សន៍<strong>ភីអិនអិន</strong>&nbsp;ជាហូរហែរ។ ក្នុងនោះ ជាមួយនឹងការមកដល់នៃសប្តាហ៍ថ្មី នៃតន្ត្រី&nbsp;<strong>Freshy happy Concert</strong>&nbsp;ក៏នឹងមិនធ្វើឲ្យទស្សនិកជន ហ្វេនៗខកបំណងនោះឡើយ។&nbsp;វត្តមានតារាចម្រៀងស្រីប្រុសល្បីៗជាច្រើន ដែលនឹងចូលរួមមកកំដរឆាកតន្ត្រីនៃកម្មវិធីខាងលើនេះ រួមមាន ដូចជា កញ្ញា&nbsp;<strong>រ៉ាប៊ី</strong>&nbsp;&nbsp;ម្ចាស់បទ មាន់ស្រែ និងបទ មីខ្មៅ ដែលជាបទកំពុងឆក់យកបេះដូងមិត្តអ្នកគាំទ្រ ជាពិសេសចង្វាក់ភ្លេង និងក្បាច់រាំយ៉ាងឡូយ។ នារសៀលថ្ងៃអាទិត្យនេះដែរ កញ្ញា នឹងត្រៀមខ្លួនជាមួយនឹងក្រុមរាំ ដែលពោរពេញដោយ ការសម្តែងក្បាច់រាំបែបទាក់ទាញ សុីនឹងចង្វាក់ភ្លេងយ៉ាងកក្រើកឆាកតន្ត្រីទាំងមូលផងដែរ។&nbsp;</p>\r\n<p><img src=\"../../../assets/images-uploads/ZMkCAYOpIkBZvYtoGA4wgsEwrbSW130MufXV4iGE.jpg\" alt=\"\" width=\"800\" height=\"800\" /></p>\r\n<p>ជាមួយគ្នានេះ វត្តមានតារាផ្សេងទៀត ដូចជា លោក&nbsp;<strong>ជុំ លីណា</strong>&nbsp;, កញ្ញា&nbsp;<strong>នីកា</strong>&nbsp;និងលោក&nbsp;<strong>ផែង សុផារិទ្ធ</strong>&nbsp;ដែលពួកគាត់ទាំងបី ក៏សុទ្ធសឹងជាតារាមានទឹកសំលេងពីរោះ ជាពិសេស លោក ជុំ លីណូ ដែលភាគទស្សនិកជន ស្គាល់រូបលោក តាមរយៈបទចម្រៀងបែបស្រុកស្រែជាច្រើនបទ កាលពីច្រើនឆ្នាំមុន។&nbsp;</p>\r\n<p><img src=\"../../../assets/images-uploads/i3qJ9pAXVRx0UORKR9rVB6Q6va0AeaKo2r0VHHLQ.jpg\" alt=\"\" width=\"800\" height=\"800\" /></p>\r\n<p><img src=\"../../../assets/images-uploads/Yv9A6EYgNSl9MagejABr6akfeRhCbVlwKkOF4Zam.jpg\" alt=\"\" width=\"800\" height=\"800\" /></p>\r\n<p><img src=\"../../../assets/images-uploads/fQEL8PfLvghdxN61MRtD2P2wRLM1ZfhHcvVQ5SUt.jpg\" alt=\"\" width=\"800\" height=\"800\" /></p>\r\n<p class=\"img-full\">សូមឲ្យកុំពេលវេលាទស្សនាកម្សាន្តនៃតន្ត្រី&nbsp;<strong>Freshy happy Concert</strong>&nbsp;រំលងផុតទៅ នារសៀលថ្ងៃអាទិត្យនេះ សូមរង់ចាំការទស្សនាការផ្សាយផ្ទាល់នៅលើកញ្ចក់ទូរទស្សន៍​<strong>ភីអិនអិន&nbsp;</strong>នៅថ្ងៃអាទិត្យ ទី ១០ ខែតុលា ឆ្នាំ ២០២១ ចាប់ពី វេលាម៉ោង ០៤ និង ៣០ នាទីរសៀល៕&nbsp;</p>\r\n<p><strong>នាំមកជូនជាពិសេសផ្តាច់មុខដោយ ទឹកផ្លែឈើ Freshy &nbsp;ពីផ្លែឈើពិត ១០០ % ។&nbsp;</strong><br />សូមទស្សនាវីដេអូខាងក្រោម៖&nbsp;</p>\r\n<p><iframe style=\"border: none; overflow: hidden;\" src=\"https://www.facebook.com/plugins/video.php?href=https%3A%2F%2Fwww.facebook.com%2FPNNTVCambodia%2Fvideos%2F654136058888209%2F&amp;show_text=0&amp;width=560\" width=\"560\" height=\"315\" frameborder=\"0\" scrolling=\"no\" allowfullscreen=\"allowfullscreen\"></iframe></p>', 1, '2021-10-09 11:31:27', '2021-10-09 11:31:27');
INSERT INTO `posts` VALUES (4, 'រឿង «ម្ទេសហឹរ ប៉ះអំបិលប្រៃ» ជារឿងភាគខ្មែរ ដែលមានគុណភាពរូបភាពច្បាស់បំផុត', 1, 2, 1, 'ថ្ងៃទី១៣ ខែតុលា ឆ្នាំ២០២១', '២០:០០-២១:០០', '២០:០០', 'ច័ន្ទ-ពុធ', 1, '101320211630076166a71f6cb3c.jpg', '<p>ចាងហ្វាងផលិតកម្មអិលឌី ភិចឆ័រ<strong>&nbsp;(LD Picture Production)&nbsp;</strong>និងជាអ្នកដឹកនាំរឿង លោក លៀក លីដា បានអះអាងថា&nbsp;<strong>រឿងភាគ &laquo;ម្ទេសហឹរ ប៉ះអំបិលប្រៃ&raquo;</strong>&nbsp;គឺជារឿងដែលមានគុណភាពរូបភាពច្បាស់បំផុត ដោយការប្រើប្រាស់ទាំងកាមេរ៉ា និងLen ដែលមិនងាយនឹងមានរឿងភាគទូរទស្សន៍ណា ប្រើប្រាស់ឡើយ។</p>\r\n<p>លោកបានថ្លែងបែបនេះ ក្នុងពេលផ្តល់បទសម្ភាសន៍ពិសេសមួយនៅក្នុង កម្មវិធីព័ត៌មានកំសាន្ត របស់ស្ថានីយទូរទស្សន៍ភីអិនអិន កាលពីថ្ងៃសុក្រ ទី២៦ ខែសីហា។ លោកបាននិយាយថា៖ &laquo;យើងប្រើប្រាស់កាមេរ៉ាប្រភេទ Film 35 mm ឯLens យើងប្រើប្រាស់ប្រភេទ Prime lens ឬ Cinema lens ដែលជាទូទៅមិនងាយគេប្រើទេសម្រាប់ថតកុនភាគ សូម្បីតែនៅក្រៅប្រទេសក៏ដោយ ដោយសារវាចាយពេលច្រើន&raquo;។</p>\r\n<p><img src=\"../../../assets/images-uploads/s2XQgg0yVh1PSNGf9Cizv1x2gwTVazzKQdt6HXel.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p>មិនតែប៉ុននោះ សម្រាប់ដំណើការនៃការកាត់តវិញ លោកបានរៀបរាប់ឲ្យដឹងថា៖ &laquo;គ្រប់ភាគនៃរឿងម្ទេសហឹរ ប៉ះអំបិលប្រៃ គឺសុទ្ធសឹងតែបានឆ្លងកាត់ការ Edit យ៉ាងសម្រិតសម្រាំងបំផុត ដោយក្រុមការងាររបស់យើង ដែលបានទទួលការបណ្តុះបណ្តាលពីបរទេស ក្នុងនោះមានដូចជាការ Edit online, offline, sound mixing, color correctionនិង mastering contrast ដោយមិនមែនគ្រាន់តែកាត់តភ្លាម ហើយចាក់ផ្សាយនោះទេ&raquo;។&nbsp;បើតាមលោក លៀក លីដា លោកមានការជឿជាក់ខ្ពស់ថា រឿងភាគបែបកំប្លែង ដែលមានគុណភាពខ្ពស់មួយនេះ ប្រាកដជាទទួលបានជោគជ័យ ពីសំណាក់ទូរទស្សនិកជន។&nbsp;</p>\r\n<p><strong>&laquo;ម្ទេសហឹរ ប៉ះអំបិលប្រៃ&raquo;</strong>&nbsp;គឺជាខ្សែភាពយន្តភាគខ្មែរមួយ ក្នុងចំណោមរឿងភាគទាំងប្រាំ របស់ភីអិនអិន ដែលនឹងចាក់បញ្ចាំង&nbsp;<strong>ចាប់ពីថ្ងៃទី៥ ខែកញ្ញា</strong>&nbsp;ខាងមុខនេះ។&nbsp;<strong>រឿងនេះនឹងមានផ្សាយជូនទស្សនា នៅរៀងរាល់ថ្ងៃចន្ទ ដល់ពុធ ចាប់ពីវេលាម៉ោង៨យប់តទៅ</strong>។&nbsp;</p>\r\n<p>រឿង &laquo;ម្ទេសហឹរ ប៉ះអំបិលប្រៃ&raquo; ជារឿងភាគមនោសញ្ចេតនាស្នេហា កំប្លែង កាច់កុងគ្នា រវាងប្តីប្រពន្ធវ័យក្មេងមួយគូ រស់នៅជាមួយនឹងម្តាយក្មេក ដែលពិបាកយល់ចិត្តស្គាល់តែកំហុស របស់កូនប្រសារស្រី។ រឿងនេះមានគំនិតអប់រំទៅដល់ម្តាយក្មេក និង កូនប្រសារសម័យថ្មីទាំងអស់ ឲ្យចេះមានការយោគយល់អធ្យាស្រ័យគ្នាទើបអាចរស់នៅ ជាមួយគ្នាប្រកបដោយសេចក្តីសុខ។ &nbsp;ខ្សែរឿងមួយនេះធានាថា ទូរទស្សនិកជនប្រាកដជាទទួលបាន នូវសំណើចសើចក្អកក្អាយ ដោយសារសំបូរទៅដោយឈុតឆាកកំប្លែងច្រើន ជាមួយនឹងការសម្តែង ដ៏ប៉ិនប្រសព្វរបស់សិល្បករល្បីៗ ដែលមានបទពិសោធន៍ ក្នុងការសម្តែងជាយូរឆ្នាំមកហើយ។ ក្នុងនោះរួមមាន<strong>កញ្ញា តូតា លោក អេវីន អ្នកនាង គ្រត លោក ជា សំណាង អ្នកស្រី ង៉ែត សុវណ្ណលីតា លោក ចាប ចៀន កញ្ញា ទឹម រដ្ឋា នាយ សុបិន</strong>&nbsp;រួមនឹងសិល្បករ-សិល្បការនី ល្បីៗមួយចំនួនទៀត។ &nbsp;</p>\r\n<p>ស្ថានីយ៍ទូរទស្សន៍ភីអិនអិន បានបេ្តជ្ញាចិត្តក្នុងការផលិតខ្សែភាពយន្តភាគ ក្នុងស្រុកឲ្យបានច្រើនជាង មួយរយម៉ោងក្នុងឆ្នាំ២០១៦នេះ ដើម្បីចាក់ផ្សាយជូនទូរទស្សនិកជន ហើយគិតជាមធ្យម&nbsp;<strong>ភីអិនអិន ត្រូវចំណាយប្រមាណ ៨០០០ដុល្លារ</strong>&nbsp;ក្នុងរយៈពេលមួយម៉ោង នៃខ្សែភាពយន្តភាគ៕</p>', 1, '2021-10-13 16:30:07', '2021-10-13 16:30:07');
INSERT INTO `posts` VALUES (5, '«សង្គ្រាមបេះដូង»ជាខ្សែភាពយន្តភាគ សម្រិតសម្រាំង ដោយអ្នកនិពន្ធខ្មែរ១០០ភាគរយ', 1, 2, 1, 'ថ្ងៃទី១៣ ខែតុលា ឆ្នាំ២០២១', 'comingsoon', 'comin', '', 1, '101320211644576166aa996bdad.jpg', '<p>ខ្សែភាពយន្តភាគរបស់ភីអិនអិនរឿង&nbsp;<strong>&laquo;សង្គ្រាមបេះដូង&raquo;&nbsp;</strong>គឺជាភាពយន្តភាគដែលត្រូវបាន សម្រិតសម្រាំងដោយ អ្នកនិពន្ធខ្មែរ១០០ភាគរយ។ នេះបើតាមការអះអាងរបស់កញ្ញា គីមអាន អារុណ ដែលជាអ្នកនិពន្ធ&nbsp;<strong>ប្រចាំផលិតកម្មខ្មែរមេគង្គ (KMF)</strong>។&nbsp;</p>\r\n<p>នៅក្នុងកិច្ចសម្ភាសន៍ពិសេស ជាមួយភីអិនអិននៅថ្ងៃអង្គារ ទី៣០ ខែសីហានេះ កញ្ញា អារុណ បានឲ្យដឹងថា៖ &laquo;រឿងសង្គ្រាមបេះដូងនេះគឺជា ការផលិតចេញពីស្នាដៃកូនខ្មែរមួយរយភាគរយ ដោយមិនមានការចំលងពីបរទេសនោះទេ ទាំងការនិពន្ធ ទាំងការដឹកនាំ ថត រួមទាំងក្រុមការងារទាំងមូល&raquo;។</p>\r\n<p><img src=\"../../../assets/images-uploads/uawIaNGMn7LgpHY2JX0k3jEbKYTLlH7k30ptVhlo.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p>កញ្ញាបានបន្តទៀតថា ខ្សែភាពយន្តនេះគឺមានការសម្រិតសម្រាំង រាល់ភាគនីមួយៗកញ្ញាព្យាយាមនិពន្ធ បញ្ចេញបញ្ចូល និងត្រួតពិនិត្យម្តងហើយ ម្តងទៀត ធ្វើយ៉ាងណាឲ្យមានភាពទាក់ទាញ និងទទួលបានប្រជាប្រិយភាព ពីទូរទស្សនិកជន។</p>\r\n<p>ពាក់ព័ន្ធទៅនឹងតួសម្តែងវិញ ត្រូវបានអ្នកដឹកនាំរឿងរបស់ KMF លោក ជុំ ចាន់ដន បញ្ជាក់ថា តួសម្តែងក្នុងរឿងនេះ សុទ្ធសឹងតែមានសមត្ថភាពក្នុងការសម្តែង មិនចាញ់តួបរទេសនោះឡើយ ក្នុងនោះមានដូចជា&nbsp;<strong>លោក ហេង នរៈកក្កដា លោក សន កាយ៉ាឌី កញ្ញា ឡាយ សម្ផស្ស និងកញ្ញា ចេស៊ីកា</strong>&nbsp;រួមនឹងតារាសម្តែង ក្នុងស្រុកមួយចំនួនទៀត។ រឿងភាគមួយនេះ ក៏ជាការផ្តល់ឱកាសដល់តារាសម្តែងថ្មីៗ ដែលមានទេពកោសល្យបានបញ្ចេញនូវសមត្ថភាព របស់ខ្លួនផងដែរ។</p>\r\n<p>&laquo;សង្គ្រាមបេះដូង&raquo; ជាវណ្ណកម្មថ្មីរបស់ផលិតកម្មខ្មែរមេគង្គ ដែលនឹងចាក់ផ្សាយនៅលើកញ្ចក់ទូរទស្សន៍&nbsp;<strong>ភីអិនអិនចាប់ពីថ្ងៃទី៨ ខែកញ្ញា</strong>&nbsp;នេះតទៅ។ ទូរទស្សនិកជនភាគច្រើន បានទទួលស្គាល់ទៅលើស្នាដៃ ផលិតរបស់ផលិតកម្មក្នុងស្រុកមួយនេះ ជាពិសេសនោះគឺរឿងចុងក្រោយគេ &laquo;តម្លៃស្នេហ៍&raquo; ដែលបានឈ្នះពានរង្វាន់ដល់ទៅ៤ ពីមហោស្រពភាពយន្តនៅហូលីវូដ&nbsp;<strong>Hollywood International Moving Pictures Film Festival (HIMPFF)</strong>។&nbsp;</p>\r\n<p>រឿង&laquo;សង្គ្រាមបេះដូង&raquo; ជារឿងរ៉ាវស្នេហាតួឯកស្រីត្រូវប្រឆាំងនឹងបេះដូងរបស់ខ្លួន ទៅរៀបការជាមួយនឹងមនុស្ស ដែលខ្លួនមិនស្រឡាញ់ជាថ្នូរនឹង ប្រាក់ជូនម្តាយដែលញៀននឹងល្បែង និងការបានបន្តនៅជិតមនុស្ស ដែលនាងស្រឡាញ់។ ភាពតានតឹងកាន់តែខ្លាំង ខណៈដែលការពិតអ្វីៗ សុទ្ធតែជាការរៀបចំទុកជាមុន ដោយមិនឲ្យនាងដឹងពីសំណាក់បុរស ជាទីស្រឡាញ់របស់នាង។ &nbsp;ខ្សែភាពយន្តភាគបែបមនោសញ្ចេតនា ការច្រណែនឈ្នានីស និងបង្កប់នូវអាទិ៍កំបំាងមួយនេះ នឹង<strong>ចាក់ផ្សាយនៅរៀងរាល់ថ្ងៃព្រហស្បតិ៍ សុក្រ និងសៅរ៍ វេលាម៉ោង៨យប់ ចាប់ពីថ្ងៃទី៨ ខែកញ្ញាតទៅ</strong>។ ភីអិនអិន ជាស្ថានីយទូរទស្សន៍ថ្មី និងទំនើបបំផុតនៅកម្ពុជា បានផ្ដល់ទុនផលិតយ៉ាងសន្ធឹកសន្ធាប់ ដល់ផលិតករខ្មែរ ដើម្បីលើកកំពស់គុណភាពភាពយន្តខ្មែរ និងបំពេញតម្រូវការកម្សាន្ត របស់ពលរដ្ឋកម្ពុជា។</p>\r\n<p>ស្ថានីយទូរទស្សន៍ភីអិនអិន បានបេ្តជ្ញាចិត្តក្នុងការផលិតខ្សែភាពយន្តភាគ ក្នុងស្រុកឲ្យបានច្រើនជាងមួយរយម៉ោង ក្នុងឆ្នាំ២០១៦នេះ ដើម្បីចាក់ផ្សាយជូនទូរទស្សនិកជន ហើយគិតជាមធ្យម ភីអិនអិន ត្រូវចំណាយប្រមាណ ៨០០០ដុល្លារ ក្នុងរយៈពេលមួយម៉ោង នៃខ្សែភាពយន្តភាគ៕</p>', 1, '2021-10-13 16:44:57', '2021-10-13 16:44:57');
INSERT INTO `posts` VALUES (6, 'មឿង សុផាណែតតារាទើបរះថ្មី ស្រវាចាប់បានដំណែង តួឯកក្នុងរឿង «ភក្តីស្នេហ៍ទ្វេភព»', 1, 2, 1, 'ថ្ងៃទី១៣ ខែតុលា ឆ្នាំ២០២១', '២០:០០-២១:០០', '២០:០០', 'ច័ន្ទ-ពុធ', 1, '101320211708136166b00d9e502.jpg', '<p>ថ្វីត្បិដទើបតែប្រឡូកចូល ក្នុងវិស័យសិល្បៈក៏ពិតមែន ប៉ុន្តែតារាសម្តែងសំបុរស្រអែម&nbsp;<strong>កញ្ញា មឿង សុផាណែត&nbsp;</strong>អាចក្តោបបានដំណែង ជាតួឯកស្រី និងមានទីផ្សារសម្តែង មិនចាញ់តារាជើងចាស់ប៉ុន្មានឡើយ ហើយកញ្ញាក៏ជាតួឯកស្រី ក្នុងខ្សែភាពយន្តភាគខ្មែរ ដែលកំពុងតែចាក់ផ្សាយនៅលើ កញ្ចក់ទូរទស្សន៍ភីអិនអិនគឺរឿង&nbsp;<strong>&laquo;ភក្តីស្នេហ៍ទ្វេរភព&raquo;</strong>។&nbsp;</p>\r\n<p><img src=\"../../../assets/images-uploads/LT5YNdwq3Wb684Xsyiv0rBMFVk0GgtVIr5ONtV8q.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p>ការសម្តែងរឿងនេះដែរ ធ្វើអោយកញ្ញាជួបផលពិបាកច្រើន ព្រោះតែកញ្ញាទើបតែប្រឡូកចូល ក្នុងវិស័យសិល្បៈប្រមាណបីឆ្នាំប៉ុណ្ណោះ ប៉ុន្តែតម្រូវអោយកញ្ញាចាប់ដៃគូ សម្តែងជាមួយនឹង<strong>លោកអ៊ុន សុទ្ធា</strong>&nbsp;ដែលជាតារាសម្តែងចាស់វស្សា &nbsp;ប៉ុន្តែការសម្តែងនេះក៏ធ្វើអោយ កញ្ញាទទួលបានបទពិសោធន៍ច្រើន ពីសំណាក់អ្នកដឹកនាំរឿង ក៏ដូចជាមានការណែនាំបន្ថែមទៀតពីលោកអ៊ុន សុទ្ធាផងដែរ។ &nbsp;ផាណែត បានប្រាប់ថា &laquo;ក្នុងខ្សែភាពយន្ត ភក្តីស្នេហ៍ទ្វេភព នេះពិតជាពិបាកច្រើនសម្រាប់ខ្ញុំ ដោយសារតែខ្ញុំជាតារាជំនាន់ក្រោយ ពីដំបូងខ្ញុំក៏មានអារម្មណ៍ភ័យខ្លះដែរ ប៉ុន្តែពេលដែលបានសម្តែង ជាមួយបងសុទ្ធាពីរ-បីដង និងមានការណែនាំបន្ថែម ធ្វើអោយខ្ញុំមានអារម្មណ៍កក់ក្តៅ និងដាក់ចិត្តថាព្យាយាម សម្តែងអោយបានល្អសម្រាប់ទស្សនិកជន&raquo;។ កញ្ញាបានបន្ថែមថា &laquo;រឿងភក្តីស្នេហ៍ទ្វេភព នេះខុសពីរឿងដែល ខ្ញុំធ្លាប់បានថតពីមុន រឿងដែលខ្ញុំថតពីមុនគឺជារឿងសម័យ ដោយឡែករឿងនេះជារឿងបែបបូរាណ ដូច្នេះទាំងការ រៀបចំខ្លួន ទាំងការស្លៀកពាក់ ទាំងការនិយាយស្តី និងការសម្តែង គឺត្រូវតែបូរាណទាំងអស់&raquo;។ ខ្សែភាពយន្តភាគខ្មែររឿង &laquo;ភក្តីស្នេហ៍ទ្វេភព&raquo; កំពុងតែទទួលបានការចាប់អារម្មណ៍ និងកំពុងតែចាក់ផ្សាយ នៅលើកញ្ចក់ទូរទស្សន៍ភីអិនអិន&nbsp;<strong>រៀងរាល់ថ្ងៃច័ន្ទ ដល់ថ្ងៃពុធ វេលាម៉ោង ៨:០០-៩:០០យប់</strong>&nbsp;៕&nbsp;</p>', 1, '2021-10-13 17:08:13', '2021-10-13 17:08:13');
INSERT INTO `posts` VALUES (7, 'រឿង «និស្ស័យកម្មព្រះភូម»', 1, 2, 2, 'ថ្ងៃទី១៤ ខែតុលា ឆ្នាំ២០២១', '១៨:០០-១៩:០០', '១៨:០០', 'ច័ន្ទ-ពុធ', 1, '101420211328416167ce199a17d.jpg', '<p><strong>រឿងនិស្ស័យកម្មព្រះភូម</strong>៖ ភាពយន្តភាគបង្ហាញពី ភាពសាវារបស់បុរសម្នាក់ ដែលធ្វើឲ្យនារីឈឺចិត្តរហូតដល់ស្លាប់។ ទោះបីជាបែបណា វិញ្ញាណរបស់នាងនៅតែមិនទៅចាប់ជាតិ រង់ចាំសងសឹកអ្នកដែលធ្លាប់ធ្វើឲ្យនាងឈឺចិត្ត ប៉ុន្តែ អំពើអាក្រក់ នៅតែមិនអាចយកឈ្នះ អំពើល្អបានដដែល។</p>\r\n<p><img src=\"../../../assets/images-uploads/I5s3uhlk5id3xpRH31bfKwojN2OVrnKJ1FTzIaCW.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p><strong>តួឯក៖ Tik Jesadaporn Pholdee និង Rita Sririta Jensen</strong></p>\r\n<p>ផ្សាយជូនទស្សនា៖&nbsp;<strong>ថ្ងៃចន្ទ-សៅរ៍ វេលាម៉ោង៦-៧យប់ នៅលើកញ្ចក់ទូរទស្សន៍ PNN</strong></p>', 1, '2021-10-14 13:28:41', '2021-10-14 13:28:41');
INSERT INTO `posts` VALUES (8, 'រឿង «ផ្ការីកក្រោមពពក»', 0, 2, 2, 'ថ្ងៃទី១៤ ខែតុលា ឆ្នាំ២០២១', '២១:០០-២២:០០', '២១:០០', 'ច័ន្ទ-ពុធ', 1, '101420211401136167d5b97fc09.jpg', '<p><strong>រឿងផ្ការីកក្រោមពពក</strong>៖ គឺជាខ្សែភាពយន្តបែបថ្មីមួយទៀត តម្រូវឲ្យព្រះអង្គម្ចាស់ ថាវីន ដែលជារាជទាយាទនៃវាំងថនឺន ត្រូវរត់គេចពីការតាមសម្លាប់ របស់ឧត្តមសេនីយបីនាក់។ ការរត់គេចនេះបានធ្វើឲ្យព្រះអង្គ បានទៅដល់ប្រទេសថៃ ហើយក៏បានទៅជួបជាមួយនារីម្នាក់គឺនាង ចម្ប៉ា។</p>\r\n<p><img src=\"../../../assets/images-uploads/hsvwwNxCne8ejbd2HhiQuAX47Dbq3FnOtoxnHi5J.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p>តួឯក៖&nbsp;<strong>Denkhun Ngamnet និង Tisha Tantiprasut &nbsp;</strong></p>\r\n<p>ផ្សាយជូនទស្សនា៖&nbsp;<strong>ថ្ងៃចន្ទ-ពុធ វេលាម៉ោង៩-១០យប់ នៅលើកញ្ចក់ទូរទស្សន៍ PNN</strong></p>', 1, '2021-10-14 14:01:13', '2021-10-14 14:01:13');
INSERT INTO `posts` VALUES (9, 'រឿង «សុភាពបុរសរចៈនុន»', 1, 2, 2, 'ថ្ងៃទី១៤ ខែតុលា ឆ្នាំ២០២១', '២១:០០-២២:០០', '២១:០០', 'ព្រហស្បតិ៍-សៅរ៍', 1, '101420211402516167d61bc6665.jpg', '<p><strong>រឿងសុភាពបុរសរចៈនុន</strong>៖ ភាពយន្តដែលបានបង្ហាញពី វិស្វករវ័យក្មេងម្នាក់ដែលមានភាពជឿជាក់ លើខ្លួនឯង។ ដោយសារតែកាងារ ទើបធ្វើឲ្យគាត់ធ្វើដំណើរទៅក្រៅប្រទេស ចៃដន្យ (រចៈនុន) ក៏បានលង់ស្រឡាញ់ ជាមួយនឹងមនុស្សស្រីម្នាក់រស់នៅព្រៃភ្នំ (Soifah)។ បើទោះបីជាពួកគេស្រឡាញ់គ្នាបែបណាក្តី ប៉ុន្តែស្នេហារបស់ពួកគេ មិនសូវជាចុះសម្រុងគ្នាប៉ុន្មានឡើយ។</p>\r\n<p><img src=\"../../../assets/images-uploads/kabfthB0ljIbfFchTR6iSYmz92XWQkEq06p84s7Q.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p>តួឯក៖&nbsp;<strong>Taew និង Bomb Tanin</strong></p>\r\n<p>ផ្សាយជូនទស្សនា៖&nbsp;<strong>ថ្ងៃព្រហស្បតិ៍-សៅរ៍ វេលាម៉ោង៩-១០យប់ នៅលើកញ្ចក់ទូរទស្សន៍ PNN</strong></p>', 1, '2021-10-14 14:02:51', '2021-10-14 14:02:51');
INSERT INTO `posts` VALUES (10, 'រឿង «រូបមន្តជីវិត»', 1, 2, 3, 'ថ្ងៃទី១៤ ខែតុលា ឆ្នាំ២០២១', 'comingsoon', 'comin', '', 1, '101420211417046167d970ee876.jpg', '<p><strong>រឿងរូបមន្តជីវិត</strong>៖ គឺជាខ្សែភាពយន្តដែលពាក់ព័ន្ធជាមួយនឹង ការធ្វើម្ហូបយ៉ាងចំណានរបស់តូឯកប្រុស<strong>&nbsp;Tony Hung (Ding Yat San)</strong>&nbsp;និងមានរហ័សនាមថា អណ្តាតមាស ដែលអាចដឹងគ្រប់រសជាតិ និងគ្រឿងផ្សំទាំងអស់នៃមុខម្ហូប និងមិនអាចមាននរណាម្នាក់ អាចប្រៀបជាមួយបានឡើយ។</p>\r\n<p><img src=\"../../../assets/images-uploads/I3E2FkYnmr8elNcEbX3GAT0ec4Z8t3TeeY8F96Dl.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p>តួឯក៖&nbsp;<strong>Tony Hung និង Sisley Choi&nbsp;</strong></p>\r\n<p>ផ្សាយជូនទស្សនា៖&nbsp;<strong>ថ្ងៃចន្ទ-ពុធ វេលាម៉ោង១១ព្រឹក-១រសៀល នៅលើកញ្ចក់ទូរទស្សន៍ PNN</strong></p>', 1, '2021-10-14 14:17:04', '2021-10-14 14:17:04');
INSERT INTO `posts` VALUES (11, 'រឿង «អាថ៍កំបាំងមរណៈ»', 0, 2, 3, 'ថ្ងៃទី១៤ ខែតុលា ឆ្នាំ២០២១', '១១:០០-១២:០០', '១១:០០', 'ច័ន្ទ-សុក្រ', 1, '101420211420596167da5bb71ff.jpg', '<p><strong>រឿងអាថ៍កំបាំងមរណៈ</strong>៖ ភាពយន្តបង្ហាញពីខ្សែជីវិតរបស់&nbsp;<strong>Wai Yat Sing (Roger Kwok)</strong>&nbsp;ដែលត្រូវបានគេចាប់ជំរិត ទៅកាន់ដែនកោះមួយ នៃប្រទេសវៀតណាម។ អំឡុងពេលនៃការជាប់ឃុំឃាំងនេះ ក្រុមគ្រួសាររបស់លោក គិតថាលោកបានស្លាប់បាត់ទៅហើយ។ ដប់ឆ្នាំក្រោយ Wai Yat Sing ក៏បានវិលត្រឡប់មកវិញ តែត្រូវបាត់បង់អ្វីៗគ្រប់យ៉ាង ដែលខ្លួនធ្លាប់មាន។ តើ Wai Yat Sing នឹងមានវិធានការបែបណា សម្រាប់ខ្សែជីវិតដ៏វែងឆ្ងាយ និងស្មុគស្មាញមួយនេះ?&nbsp;</p>\r\n<p><img src=\"../../../assets/images-uploads/SX3YyRdvmZsfNkaOQA5Xb9kj3cD99dHSpjhHeLLV.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p>តួឯក៖<strong>&nbsp;Roger Kwok និង Joey Meng</strong></p>\r\n<p>ផ្សាយជូនទស្សនា៖&nbsp;<strong>ថ្ងៃចន្ទ-សុក្រ វេលាម៉ោង១១ ព្រឹក -១២ថ្ងៃត្រង់ នៅលើកញ្ចក់ទូរទស្សន៍ PNN</strong></p>', 1, '2021-10-14 14:20:59', '2021-10-14 14:20:59');
INSERT INTO `posts` VALUES (12, 'រឿង «ល្បិចក្នុងវង់ល្បែង»', 1, 2, 3, 'ថ្ងៃទី១៤ ខែតុលា ឆ្នាំ២០២១', '១១:០០-១៣:០០', '១១:០០', 'ច័ន្ទ-សុក្រ', 1, '101420211423176167dae54bf26.jpg', '<p><strong>រឿងល្បិចក្នុងវង់ល្បែង</strong>៖ គឺជារសជាតិថ្មីមួយទៀត ដែលរៀបរាប់ពីការសងសឹក ល្បិចកិចកល ដើម្បីក្លាយជាអ្នកខ្លាំងក្នុងវង់ល្បែង រហូតដល់ថ្នាក់យកជីវិត មកភ្នាល់ដាក់លើតុល្បែង ឈ្នះបានលុយ តែបើចាញ់នឹងត្រូវអស់ជីវិត។</p>\r\n<p><img src=\"../../../assets/images-uploads/1a6P9ms9hIjR10g6ALzpXhCIde3cy9FxRTtqobfl.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p>តួឯក៖<strong>&nbsp;Ruco Chan និង Rosina Lam</strong></p>\r\n<p>ផ្សាយជូនទស្សនា៖&nbsp;<strong>ថ្ងៃចន្ទ-សុក្រ វេលាម៉ោង១២ ថ្ងៃត្រង់ -១រសៀល នៅលើកញ្ចក់ទូរទស្សន៍ PNN</strong></p>\r\n<p>សូមទស្សនាឈុតខ្លីៗ</p>\r\n<p><iframe style=\"border: none; overflow: hidden;\" src=\"https://www.facebook.com/plugins/video.php?href=https%3A%2F%2Fwww.facebook.com%2FPNNTVCambodia%2Fvideos%2F1443876789017372%2F&amp;show_text=0&amp;width=560\" width=\"560\" height=\"315\" frameborder=\"0\" scrolling=\"no\" allowfullscreen=\"allowfullscreen\"></iframe></p>', 1, '2021-10-14 14:23:17', '2021-10-14 14:23:17');
INSERT INTO `posts` VALUES (13, 'មូលហេតុមួយចំនួន នាំឲ្យប្រលោមលោករឿង «បំភ្លេចមិនបាន» ទទួលបានជោគជ័យខ្លាំង', 1, 1, NULL, 'ថ្ងៃទី១៤ ខែតុលា ឆ្នាំ២០២១', NULL, NULL, NULL, 1, '101420211517296167e79947e02.jpg', '<p><strong>ប្រលោមលោករឿង &laquo;បំភ្លេចមិនបាន&raquo;&nbsp;</strong>ដែលនិពន្ធដោយអ្នកស្រី<strong>&nbsp;ប៉ាល់ វណ្ណារីរក្ស&nbsp;</strong>គឺជារឿងដែលជោគជ័យ និងទទួលបានការគាំទ្រច្រើន ពីសំណាក់មហាជន ទាំងក្នុងនិងក្រៅប្រទេស ហើយក៏ជាប្រលោមលោក ដែលត្រូវបានជាប់លេខមួយស្ទួន និងទទួលបានពានរង្វាន់ ព្រះសីហនុរាជ ឆ្នាំ១៩៩៥។&nbsp;</p>\r\n<p><img src=\"../../../assets/images-uploads/tl9WvSSr4d2iZtGwaKBQ6Wj85WRRXKsJpTfmQGVc.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p>មូលហេតុដែលនាំឲ្យប្រលោមលោករឿង &laquo;បំភ្លេចមិនបាន&raquo; ទទួលបានលេខមួយស្ទួន ដោយសារតែរឿងនេះ បានបញ្ចូលខ្លឹមសារអប់រំល្អច្រើន ការតស៊ូ ការដោះស្រាយបញ្ហាដោយប្រើបញ្ញា និងធ្វើឲ្យមនុស្សចេះតបស្នងសងគុណ ដល់អ្នកដែលធ្លាប់ជួយ។&nbsp;</p>\r\n<p>មួយវិញទៀត គឺបង្ហាញពីស្នេហាស្មោះស្ម័គ្រ ដែលមិនអាចបំភ្លេចបាន បើទោះបីជាមានការបំបែកបំបាក់ពីអ្នកដទៃក៏ដោយ នេះបើយោងទៅតាមកិច្ចសំភាសន៍ពិសេស របស់ភីអិនអិនជាមួយអ្នកស្រី ប៉ាល់ វណ្ណារីរក្ស។ ជាដំណឹងល្អមួយសម្រាប់ប្រិយមិត្ត ដែលធ្លាប់គាំទ្ររឿងប្រលោមលោក &laquo;បំភ្លេចមិនបាន&raquo; នឹងបានទស្សនាជារឿងភាគវិញម្តង ដែលត្រូវចាក់ផ្សាយនៅលើ កញ្ចក់ទូរទស្សន៍ភីអិនអិន។&nbsp;</p>\r\n<p><img src=\"../../../assets/images-uploads/CXZjN0OWKrv6kOQIVTUnf1rxvjRnkNpb8Wp7EMA3.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p>&laquo;បំភ្លេចមិនបាន&raquo; គ្រងតំណែងតួឯកដោយតារាទឹកភ្នែក នី មុន្នីនាថ ចាប់ដៃគូជាមួយលោក អូន ឧស្សាហ៍ រួមនឹងសិល្បករ សិល្បការនីជាច្រើនរូបទៀត។&nbsp;</p>\r\n<p>ខ្សែភាពយន្តនេះ នឹងត្រូវចាក់ផ្សាយ&nbsp;<strong>ចាប់ពីថ្ងៃទី ២៣ ខែកុម្ភៈ រៀងរាល់ថ្ងៃព្រហស្បតិ៍ ដល់ សៅរ៍ វេលាម៉ោង ៨យប់តទៅ</strong>&nbsp;៕</p>', 1, '2021-10-14 15:17:29', '2021-10-14 15:17:29');
INSERT INTO `posts` VALUES (14, 'ល្អមើលទៀតហើយ! ខ្សែភាពយន្តភាគហុងកុង TVB «អធិរាជសៀងហៃ» របស់ PNN', 0, 1, NULL, 'ថ្ងៃទី១៤ ខែតុលា ឆ្នាំ២០២១', NULL, NULL, NULL, 1, '101420211532456167eb2da180c.jpg', '<p>ខ្សែភាពយន្តភាគហុងកុងTVB<strong>&nbsp;&laquo;អធិរាជសៀងហៃ&raquo;&nbsp;</strong>នាំមកនូវចំណីចក្ខុថ្មី សម្រាប់ទស្សនិកជននៅកម្ពុជា ដោយខ្សែរឿងនេះមានលាយឡំទាំងកំប្លែង មនោសញ្ចេតនា បូករួមនឹងសមត្ថភាពសម្តែង របស់តួអង្គល្បីៗ នៅក្នុងខ្សែភាពយន្តនេះ ដូចជា<strong>&nbsp;Kenneth Ma, Niki Chow, Mandy Wong</strong>&nbsp;រួមនឹងតារាល្បីៗជាច្រើនរូបទៀត។</p>\r\n<p><img src=\"../../../assets/images-uploads/i4yPOppcyaNfTuEBkI6NiWu5ccOcFcBGuBATmRDt.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p>&laquo;អធិរាជសៀងហៃ&raquo; ជាភាពយន្តដែលរៀបរាប់ពីការ តស៊ូពុះពារគ្រប់ឧបសគ្គរបស់&nbsp;<strong>Chu Gam Chun (Kenneth Ma)&nbsp;</strong>ព្រោះតែចង់បាននារីម្នាក់ ដែលខ្លួនស្រឡាញ់គឺនាង&nbsp;<strong>Yi Yung Yung (Niki Chow)</strong>&nbsp;ប៉ុន្តែត្រូវបានរារាំងពីជីតារបស់នាង&nbsp;<strong>Yi Sang Kei (Joseph Lee)&nbsp;</strong>ព្រោះតែ Chu Gam Chun គឺជាជនសាមញ្ញ និងក្រីក្រម្នាក់។&nbsp;មូលហេតុនេះហើយទើបធ្វើឲ្យ Chu Gam Chun ខំប្រឹងប្រែងគ្រប់វិធី ដើម្បីបានប្រាក់ច្រើន។&nbsp;បន្ទាប់មកChu Gam Chun បានក្លាយជា &laquo;អធិរាជនៅសៀងហៃ&raquo;។</p>\r\n<p>&laquo;អធិរាជសៀងហៃ&raquo; គឺជាខ្សែភាពយន្តដែលធ្លាប់ទទួលបានភាព ល្បីល្បាញខ្លាំងនៅហុងកុងនាចុងឆ្នាំ ២០១៦។ ខ្សែភាពយន្តដ៏ល្អមួយនេះ នឹងមកដល់ប្រទេសកម្ពុជា នៅលើកញ្ចក់ទូរទស្សន៍ភីអិនអិន&nbsp;<strong>នាថ្ងៃទី ២៧ ខែកុម្ភៈ វេលាម៉ោង ១១:០០-១៣:០០ រៀងរាល់ថ្ងៃចន្ទ ដល់ថ្ងៃពុធ&nbsp;</strong>បន្ទាប់ពីរឿង&nbsp;&laquo;មិត្តភាពប្រែឫស្យា&raquo;៕</p>', 1, '2021-10-14 15:32:45', '2021-10-14 15:32:45');
INSERT INTO `posts` VALUES (15, 'ទស្សនាបច្ចុប្បន្នភាពនៃជំងឺ COVID-19 នៅក្នុងកម្មវិធី កម្ពុជាល្ងាចនេះ របស់ភីអិនអិន', 1, 1, NULL, 'ថ្ងៃទី១៤ ខែតុលា ឆ្នាំ២០២១', NULL, NULL, NULL, 1, '101420211538346167ec8aa30bf.jpg', '<p>ជំងឺ<strong>&nbsp;Covid-19&nbsp;</strong>កំពុងតែគម្រាមកំហែងជីវិតមនុស្សយ៉ាងធ្ងន់ធ្ងរនៅជុំវិញពិភពលោក ខណៈស្ថាននៃការឆ្លងវីរុសថ្មីនេះនៅតាមបណ្ដាប្រទេសនានាគឺជាក្ដីព្រួយបារម្ភរួមរបស់ប្រជាជននៅទូទាំងពិភពលោក។ ដើម្បីជម្រាបជូនព័ត៌មានច្បាស់លាស់នៃស្ថានភាពជំងឺនេះក្នុងប្រទេសកម្ពុជា ដ៏ដូចជានៅជុំវិញពិភពលោក ភីអិនអិន បានប្រើប្រាស់បច្ចេកវិទ្យា&nbsp;<strong>Smart TV&nbsp;</strong>ដើម្បីរាយការណ៍អំពីបច្ចុប្បន្នភាពនៃជំងឺ&nbsp;<strong>Covid-19</strong>&nbsp;។</p>\r\n<p><img src=\"../../../assets/images-uploads/9Uz6sBovTrS8tTmU20wHhecaKrpAzymzxFE3o3qd.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p><img src=\"../../../assets/images-uploads/ZTaVwIhE3NawawjQvGER9KIT3GDXvQO2StqyO3fa.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p><img src=\"../../../assets/images-uploads/3TZ4qJbhltx4aLsfHANG1BQ41rYdCgtruQiMALJg.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p>ការរាយការណ៍ពិសេសនេះធ្វើឡើងក្នុងកម្មវិធី កម្ពុជាល្ងាចនេះ ក្នុងវគ្គ បច្ចុប្បន្នភាព&nbsp;<strong>Covid-19&nbsp;</strong>ដែលមានការផ្សាយជូនចាប់ពីថ្ងៃចន្ទ ដល់ថ្ងៃសុក្រ វេលាម៉ោង ៥ ដល់ម៉ោង ៦ល្ងាច នៅលើកញ្ចក់ទូរទស្សន៍ភីអិនអិន។&nbsp;គិតមកដល់ព្រឹកថ្ងៃទី២៤&nbsp;ខែមេសានេះ ប្រទេសកម្ពុជាមានអ្នកឆ្លងសរុបចំនួន ១២២នាក់ ព្យាបាលជាសះស្បើយចំនួន១១០នាក់ និងពុំមានអ្នកស្លាប់ដោយសារជំងឺនេះនៅឡើយទេ៕&nbsp;</p>\r\n<p><img src=\"../../../assets/images-uploads/zPwDsRazrQ82ZCDr8jkrnGEirGn9OLQJATfNnDyx.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p><img src=\"../../../assets/images-uploads/vhIrpZPKLK9uVWx6ywmJ2W0nsF35wuZpZqrTDcRZ.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p><img src=\"../../../assets/images-uploads/ADmRF5czD9pUyTygQCIuL0YaA0D90sT7BkwVOf8N.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p><strong>ទស្សនាការបង្ហាញខាងក្រោម៖&nbsp;</strong></p>\r\n<p><strong><iframe style=\"border: none; overflow: hidden;\" src=\"https://www.facebook.com/plugins/video.php?href=https%3A%2F%2Fwww.facebook.com%2FPNNTVNews%2Fvideos%2F220135515986503%2F&amp;show_text=0&amp;width=560\" width=\"560\" height=\"315\" frameborder=\"0\" scrolling=\"no\" allowfullscreen=\"allowfullscreen\"></iframe></strong></p>', 1, '2021-10-14 15:38:34', '2021-10-14 15:38:34');
INSERT INTO `posts` VALUES (16, 'Freshy Happy Concert', 0, 3, NULL, 'ថ្ងៃទី១៦ ខែតុលា ឆ្នាំ២០២១', '១៦:៣០-១៩:០០', '១៦:៣០', 'រៀងរាល់ថ្ងៃអាទិត្យ', 1, '10162021075835616a23bbb3f70.jpg', '<div class=\"paragraph\">\r\n<p><em>កម្មវិធីតន្រី្ត Freshy Happy Concert កំពុងតែទទួលបានប្រជាប្រិយភាពខ្លាំងពីសំណាក់ទស្សនិកជន ដោយសារតែមានការចូលរួមពីសំណាក់តារាចម្រៀងល្បីៗកំពុងពេញនិយម ដែលអញ្ជើញមកពីគ្រប់ផលិតកម្មក្នុងប្រទេសកម្ពុជា។&nbsp;</em></p>\r\n<p><em>ចាប់តាំងពីដំណើរការកម្មវិធីរហូតមកដល់បច្ចុប្បន្ននេះ ទស្សនិកជនក៏បានទទួលអារម្មណ៍រីករាយ ស្រស់ស្រាយ ជាមួយបទចម្រៀងគ្រប់ចង្វាក់ ជាពិសេសថែមទាំងបានទស្សនាពីការសម្តែងឈុតពិសេសពីសំណាក់តារាចម្រៀងដែលបានចូលរួមក្នុងកម្មវិធីផងដែរ។&nbsp;</em></p>\r\n<p><em>កម្មវិធី Freshy Happy Concert ផ្សាយផ្ទាល់នៅលើកញ្ចក់ទូរទស្សន៍ភីអិនអិន រៀងរាល់ថ្ងៃអាទិត្យ វេលាម៉ោង ៤:៣០នាទីល្ងាចតទៅ។</em></p>\r\n</div>\r\n<div class=\"dateTime\">\r\n<p><img src=\"../../../assets/images-uploads/CpULA1UP2qg7wnBCZrcbqYr6HqyDeOPUzYeBosuy.jpg\" alt=\"\" width=\"800\" height=\"800\" /></p>\r\n</div>', 1, '2021-10-16 07:58:35', '2021-10-16 07:58:35');
INSERT INTO `posts` VALUES (17, 'Boostrong Rock 2K21 Concert', 0, 3, NULL, 'ថ្ងៃទី១៦ ខែតុលា ឆ្នាំ២០២១', '១៦:៣០-១៩:០០', '១៦:៣០', 'រៀងរាល់ថ្ងៃសៅរ៍', 1, '10162021080442616a252ab73db.jpg', '<p><strong>Boostrong</strong>: ជាកម្មវិធីតន្ត្រីសម័យប្រជុំដោយតារាល្បីៗ ជាពិសេសជារៀងរាល់ខែ​កម្មវិធីនេះតែងតែបានអញ្ជើញតារាថៃមកជួបជាមួយប្រិយមិត្តផ្ទាល់​ ដោយពួកគាត់នឹងបកស្រាយបទចម្រៀងល្បីរបស់ពួកគាត់។​ ជាពិសេសជារៀងរាល់ចុងកម្មវិធី តែងតែមាការផ្តល់ជូនសំណាង​ទៅដល់ទស្សនិកជន ជាមួយកម្មវិធី ប៊ូស្ត្រងតេឈ្នះលុយ ដែលមាន​ទឹកប្រាក់ចាប់ពី&nbsp;<strong>២០០,០០០ (២សែនរៀល)</strong>។</p>\r\n<p>កម្មវិធីនេះផ្សាយផ្ទាល់រៀងរាល់ថ្ងៃសៅរ៍</p>\r\n<p>​វេលាម៉ោង៤:៣០នាទៅល្ងាចតទៅ</p>\r\n<p>នៅស្ទីតយោ&nbsp;<strong>ភីអិនអិន</strong>៕</p>\r\n<p><img src=\"../../../assets/images-uploads/nevMCBFfMjOclY6PSuZsM4pM96l3NXreog3LgWW7.jpg\" alt=\"\" width=\"800\" height=\"800\" /></p>', 1, '2021-10-16 08:04:42', '2021-10-16 08:04:42');
INSERT INTO `posts` VALUES (18, 'Ganzberg One Strike', 0, 3, NULL, 'ថ្ងៃទី១៦ ខែតុលា ឆ្នាំ២០២១', '១៣:០០-១៥:៣០', '១៣:០០', 'រៀងរាល់ថ្ងៃអាទិត្យ', 1, '10162021081124616a26bc4e097.png', '<p>សង្វៀនប្រដាល់គុនខ្មែររបស់ស្ថានីយទូរទស្សន៍PNNដែលគ្រប់គ្នាទន្ទឹងរង់ចាំ បានវិលមកវិញនាថ្ងៃទី ០៤ ខែ កក្កដា ឆ្នាំ ២០២១ នេះហើយ ។ Ganzberg One Strike&nbsp;គឹជាកម្មវិធីប្រដាល់ថ្មី ប្លែក ពុំធ្លាប់មានពីមុនមក ដែលនឹងផ្តល់ឱកាសដល់អ្នកប្រដាល់ជំនាន់ថ្មី បានបញ្ចេញថ្វីស្នៀត ឈានទៅរកភាពជោគជ័យលើវិស័យគុនខ្មែរ។&nbsp;</p>\r\n<p>ក្រៅពីយុទ្ធនាការដណ្ដើមខ្សែក្រវាត់អមដោយប្រាក់៤០លានរៀលដែលពោរពេញទៅដោយជើងខ្លាំងគុនខ្មែរទម្ងន់៥៧គីឡូក្រាម១៦រូប កម្មវិធី Ganzberg One Strikeក៏បានបង្កើតទស្សនីយ៍ភាពដ៏ប្លែកដែលជាចំណីចក្ខុថ្មីមួយទៀតសម្រាប់អ្នកនិយមគាំទ្រវិស័យមួយនេះនោះគឺការប្រកួត One Strike ដែលជាការប្រកួត គ្មានការស្មើ គឺមានតែចាញ់ ឈ្នះ&nbsp;ការបោះបង់ការប្រកួត ឬ អាជ្ញាកណ្ដាលបញ្ឈប់តែប៉ុណ្ណោះ។ដើម្បីកុំឲ្យទស្សនីយ៍ភាពដ៏អស្ចារ្យ ចំឡែកតែមួយគត់នៅកម្ពុជា រំលងផុតពីអារម្មណ៍អ្នកស្នេហាវិស័យគុនខ្មែរ កុំភ្លេចរង់ចាំទស្សនាកម្មវិធី Ganzberg One Strike&nbsp;ផ្សាយផ្ទាល់នៅលើកញ្ចក់ទូរទស្សន៍ភីអិនអិន ផេកផ្លូវការ Ganzberg និងផេក PNN Sports ចាប់ពីថ្ងៃទី ០៤ កក្កដា ចាប់ពីម៉ោង១រសៀលតទៅ។</p>\r\n<p><strong>Ganzberg One Strike ទទួលបានការឧបត្ថម្ភពិសេសផ្ដាច់មុខដោយ ស្រាបៀរហ្គេនស៍បឺគ ផលិតដោយជនជាតិអាល្លឺម៉ង់ ឈ្នះមេដាយកម្រិតពិភពលោក២០២១៕</strong></p>\r\n<p><strong><img src=\"../../../assets/images-uploads/0HfWA49ZdDXRsk7vCGrIBgnPPXCAGTFDDtVB7ULo.png\" alt=\"\" width=\"800\" height=\"800\" /></strong></p>', 1, '2021-10-16 08:11:24', '2021-10-16 08:11:24');
INSERT INTO `posts` VALUES (19, 'អ្នកជិតខាង', 0, 3, NULL, 'ថ្ងៃទី១៦ ខែតុលា ឆ្នាំ២០២១', '២១:០០-២២:០០', '២១:០០', 'រៀងរាល់ថ្ងៃសៅរ៍', 1, '10162021081338616a274244362.jpg', '<p>កម្មវិធី&laquo;<strong>អ្នកជិតខាង</strong>&raquo; គឺកម្មវិធីមួយបង្ហាញជូនជាមួយទស្សនីយភាពដែលមិនធ្លាប់ជួប មិនធ្លាប់បានទស្សនា និងចែករំលែកចំណីអារម្មណ៍គ្រប់រសជាតិ&nbsp;ការជជែកគ្នាដោយផ្តល់នូវភាពសប្បាយរីករាយ និងការជីកឬសជីកគល់ពីប្រវត្តិរបស់តារាកិត្តិយសដែលធ្លាប់លំបាកខ្លាំងនិងចាក់ដោតអារម្មណ៍ រហូតទប់ទឹកភ្នែកលែងជាប់។&nbsp;តារាកិត្តិយសដែលចូលរួមក្នុងកម្មវិធីនេះមានទាំងតារាចម្រៀង តារាសម្តែង អ្នករាំ និងអ្នកដែលកំពុងតែជោគជ័យខ្លាំងលើវិថីមុខជំនួញជាដើម។&nbsp;</p>\r\n<p>កម្មវិធី &laquo;<strong>អ្នកជិតខាង</strong>&raquo; ផលិតឡើងសម្រាប់ការផ្សាយរយៈពេលមួយម៉ោងពេញគឺចាប់ពីម៉ោង ៩:០០ ដល់ម៉ោង ១០:០០ យប់ នឹងផ្តើមដំណើរការចាក់ផ្សាយចាប់ពីថ្ងៃសៅរ៍ ទី០២ ខែតុលា ឆ្នាំ២០២១ តទៅនៅលើកញ្ចក់ ទូរទស្សន៍ភីអិនអិន តែមួយគត់៕</p>\r\n<p><img src=\"../../../assets/images-uploads/1GcRnQ6BRdXcnBTDA7HH6kbZqWQ72djMvaM6QuJB.jpg\" alt=\"\" width=\"800\" height=\"800\" /></p>', 1, '2021-10-16 08:13:38', '2021-10-16 08:13:38');
INSERT INTO `posts` VALUES (20, 'តារាសម្តែងល្បីៗ ក្នុងរឿងភាគខ្មែរ របស់PNN ជួបប្រិយមិត្តរបស់ខ្លួន នៅផ្សារទំនើប អ៊ីអន', 0, 4, NULL, 'ថ្ងៃទី១៦ ខែតុលា ឆ្នាំ២០២១', NULL, NULL, NULL, 1, '10162021082926616a2af63a004.jpg', '<p>សិល្បករល្បីៗ របស់កម្ពុជា ដែលជាតួសម្តែង នៅក្នុងរឿងភាគចំនួនពីរ របស់ភីអិនអិន បានជួបជាមួយប្រិយមិត្តរបស់ខ្លួន ដោយផ្ទាល់នៅផ្សារទំនើបអ៊ីអន&nbsp;<strong>កាលពីថ្ងៃសុក្រ ទី០២ ខែកញ្ញា ឆ្នាំ២០១៦</strong>។&nbsp;នេះជាព្រឹត្តិការណ៍ ដំបូងបង្អស់មិនធ្លាប់មានពីមុនមក ដែលតារាសម្តែងនៅក្នុងខ្សែភាពយន្តភាគខ្មែរ ជួបជាមួយនឹងប្រិយមិត្ត របស់ខ្លួនដោយផ្ទាល់បែបនេះ។</p>\r\n<p><img src=\"../../../assets/images-uploads/U6kuHxcYkCKZcILyTFRlfYZkbmoB2mdFKsl33t84.jpg\" alt=\"\" width=\"800\" height=\"533\" /></p>\r\n<p>វត្តមានតារាសម្តែងល្បីៗ ដែលចូលរួមក្នុងជំនួបពិសេសនេះ មានដូចជា&nbsp;<strong>លោក អេវីន កញ្ញា តូតា អ្នកនាង គ្រត លោក ជា សំណាង</strong>&nbsp;ដែលពួកគេមកពីផលិតកម្មអិលឌីភិចឆ័រ រឿងម្ទេសហឹរ ប៉ះអំបិលប្រៃ។ ដោយឡែកតួសម្តែង ដែលមកពីផលិតកម្មខ្មែរមេគង្គ រឿងសង្គ្រាមបេះដូង វិញមាន&nbsp;<strong>លោក ហេង នរៈកក្កដា លោក សន កាយ៉ាឌី កញ្ញា ឡាយ សម្ផស្ស កញ្ញា ចេស៊ីកា អ្នកស្រី ង៉ែត សុវណ្ណលីតា កញ្ញា ឃីង សុរិយា</strong>&nbsp;រួមនឹងវត្តមានតារាល្បីៗ ជាច្រើនរូបទៀត។</p>\r\n<p><img src=\"../../../assets/images-uploads/XWlczEXRJXGjFm2ZhbpoyTyUp5r8sGfPzImQ7fuY.jpg\" alt=\"\" width=\"800\" height=\"533\" /></p>\r\n<p><img src=\"../../../assets/images-uploads/cUTtR8eFX3hXrNBXQ3yiICrwKhqnkFDZuYaXceni.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p><strong>លោក Glen Felgate&nbsp;</strong>នាយកប្រតិបត្តិស្ថានីយទូរទស្សន៍ភីអិនអិន បាននិយាយថា៖ &laquo;ភីអិនអិន បានវិនិយោគទឹកប្រាក់ យ៉ាងច្រើនសន្ធឹកសន្ធាប់ ទៅលើសិល្បករក្នុងស្រុក អ្នកសរសេរScript ក្នុងស្រុក និងផលិតកម្មក្នុងស្រុក ដើម្បីសម្រិតសម្រាំងរឿងភាគខ្មែរ ដែលល្អគួរជាទីចាប់អារម្មណ៍ជូនដល់អ្នកទស្សនា ហើយភីអិនអិន ក៏បានវិនិយោគទឹកប្រាក់រាប់ម៉ឺនដុល្លារផ្សេងទៀតផងដែរ ដើម្បីផ្សព្វផ្សាយរឿងភាគ ដែលផលិតបានទាំងនោះ&raquo;។</p>\r\n<p><strong>ស្ថានីយ៍ទូរទស្សន៍ភីអិនអិន</strong>&nbsp;បានបេ្តជ្ញាចិត្តក្នុងការផលិតខ្សែភាពយន្តភាគក្នុងស្រុក ឲ្យបានច្រើនជាងមួយរយម៉ោងក្នុងឆ្នាំ២០១៦ ដើម្បីចាក់ផ្សាយជូនទូរទស្សនិកជន ហើយគិតជាមធ្យម ភីអិនអិន ត្រូវចំណាយប្រមាណ&nbsp;<strong>៨០០០ដុល្លារ&nbsp;</strong>ក្នុងរយៈពេលមួយម៉ោងនៃខ្សែភាពយន្តភាគ៕</p>', 1, '2021-10-16 08:29:26', '2021-10-16 08:29:26');
INSERT INTO `posts` VALUES (21, 'សកម្មភាព ពិសេសៗរបស់ JAMES និង BELLA ក្នុងដំណើរមកដល់ ទឹកដីនៃប្រទេសកម្ពុជា', 0, 4, NULL, 'ថ្ងៃទី១៦ ខែតុលា ឆ្នាំ២០២១', NULL, NULL, NULL, 1, '10162021083404616a2c0c6b860.jpg', '<p><strong>កាលពីថ្ងៃអាទិត្យ ទី៩ ខែតុលា ឆ្នាំ២០១៦</strong>&nbsp;កន្លងទៅ ស្ថានីយទូរទស្សន៍ភីអិនអិន បានរៀបចំកម្មវិធីផ្សាយផ្ទាល់ពិសេសមួយគឺ<strong>&nbsp;&laquo;វេទិកាតារាថៃប្រចាំPNN 2016&raquo;&nbsp;</strong>នៅផ្សារទំនើបអ៊ីអន ដោយមានការអញ្ជើញចូលរួម ពីសំណាក់តារាសម្តែងថៃពីរដួង គឺលោក&nbsp;<strong>James Jirayu និងកញ្ញា Bella Ranee</strong>។ &nbsp;ពេលដែលតារាទាំងពីរដួង មកដល់ព្រលានយន្តហោះអន្តរជាតិពោធិ៍ចិនតុងភា្លម យើងសង្កេតឃើញក្រុមអ្នកគាំទ្រ ជាច្រើនកុះករ បានស្វាគមន៍យ៉ាងកក់ក្តៅ អមជាមួយទឹកចិត្តរំភើបរីករាយ នៅពេលបានជួបផ្ទាល់ ជាមួយតារាក្នុងដួងចិត្តរបស់ពួកគេ។</p>\r\n<p><img src=\"../../../assets/images-uploads/XU3Aqh8RDErTn1sY8TWgjeBgeZGB8EqdqELuOPML.jpg\" alt=\"\" width=\"800\" height=\"533\" /></p>\r\n<p>បន្ទាប់ពីកិច្ចស្វាគមន៍នៅព្រលានយន្តហោះ បានបញ្ចប់ទៅតារាថៃទាំងពីរដួង រួមជាមួយក្រុមកាងារ ស្ថានីយទូរទស្សន៍ភីអិនអិន បានបន្តដំណើរទៅផ្សារទំនើបអ៊ីអន និងបានពិសារអាហារថ្ងៃត្រង់ នៅភោជនីយដ្ឋានFuji ត្រៀមបង្ហាញខ្លួននៅក្នុងកម្មវិធី &laquo;វេទិកាតារាថៃប្រចាំPNN 2016&raquo;។ កម្មវិធី &laquo;វេទិកាតារាថៃរបស់ PNN 2016&raquo; ដែលមានការចូលរួមពី James និង Bella បានបញ្ចប់ទៅដោយជោគជ័យ នៅវេលាម៉ោង៣ រសៀលថ្ងៃដដែល។</p>\r\n<p><img src=\"../../../assets/images-uploads/LFEIXDWXCnhPYfd8iZq6rtz5DAo7WR3jquZrrwxO.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p><img src=\"../../../assets/images-uploads/sxYJQ6J8EcZ7DsPnLSQISZE8hAGu8l3RwqY2GpzX.jpg\" alt=\"\" width=\"800\" height=\"1200\" /></p>\r\n<p>ឈានចូលមកដល់<strong>ថ្ងៃចន្ទ ទី១០ ខែតុលា</strong>&nbsp;លោក James Jirayu បានមកទស្សនកិច្ចដោយផ្ទាល់ នៅស្ថានីយទូរទស្សន៍ភីអិនអិន ព្រមទាំងបានផ្តល់កិច្ចសម្ភាសន៍ពិសេសមួយ ជាមួយពិធីការនីដ៏ស្រស់ស្អាត&nbsp;<strong>គឺកញ្ញាជីមមី</strong>។&nbsp;បន្ទាប់ពីកិច្ចសម្ភាសន៍ បានបញ្ចប់លោក James ក៏បានទៅទស្សនាបន្ទប់បញ្ចូលសំឡេង ដ៏ទំនើបរបស់ភីអិនអិន និងបានជួបផ្ទាល់ជាមួយលោក<strong>&nbsp;ឌី សុខរិទ្</strong>ធ ដែលគាត់គឺជាអ្នកបញ្ចូលសំលេងតួលោក James ក្នុងរឿង ភរិយាបណ្តូលចិត្ត។&nbsp;<br />&nbsp;</p>\r\n<p><strong>អីយ៉ាស់! អ្នកបញ្ចូលសំឡេង James ខ្មែរ និង James ពិតប្រាកដជួបគ្នាហើយតើ!</strong></p>\r\n<p><strong><img src=\"../../../assets/images-uploads/aMr0rFYFT83evsjtlhKJXfVQnYH70CsBjQNtWJrX.jpg\" alt=\"\" width=\"800\" height=\"533\" /></strong></p>\r\n<p>ដំណើរទស្សនកិច្ចរបស់ James នៅស្ថានីយទូរទស្សន៍ភីអិនអិន បានបញ្ចប់ទៅដោយភាពរីករាយ និងទទួលបានការស្វាគមន៍ យ៉ាងយកចិត្តទុកដាក់ ពីសំណាក់ក្រុមកាងារទាំងអស់ របស់ភីអិនអិន។&nbsp;នៅមិនទាន់អស់នៅឡើយ James បានបន្តដំណើរទស្សនកិច្ចពិសេសនេះទៅកាន់សណ្ឋាគារ ដ៏ប្រណិតជាងគេនៅកម្ពុជា គឺសណ្ឋាគារ&nbsp;<strong>Garden City</strong>&nbsp;និងបានផ្តល់ឱកាសទៅដល់ក្រុមអ្នកសារព័ត៌មាន ធ្វើបទសម្ភាសន៍ ដល់រូបលោកពាក់ព័ន្ធដំណើរមកដល់ ទឹកដីនៃប្រទេសកម្ពុជា រួមជាមួយសកម្មភាពកាងារផ្សេងៗ ព្រមទាំងទទួលទានអាហារថ្ងៃត្រង់ ជាមួយថ្នាក់ដឹកនាំភីអិនអិន និងតារាភាពយន្តខ្មែរ មួយចំនួនដែលនឹងបង្ហាញមុខក្នុង ខ្សែភាពយន្តភាគខ្មែរនៅភីអិនអិន ។&nbsp;</p>\r\n<p>លោក James Jirayu បានធ្វើដំណើរត្រឡប់ទៅវិញ នៅវេលាម៉ោង១រសៀល អមដំណើរដោយក្រុមកាងារ នៃស្ថានីយទូរទស្សន៍ភីអិនអិន រួមជាមួយក្រុមអ្នកគាំទ្រមួយចំនួនផងដែរ។ សកម្មភាពទាំងនេះ បានចាក់ផ្សាយជាពិសេសនៅលើ កញ្ចក់ទូរទស្សន៍ភីអិនអិន&nbsp;<strong>នៅថ្ងៃសៅរ៍ ទី១៥ និង ២២ តុលា ឆ្នាំ២០១៦ វេលាម៉ោង៧ យប់</strong>។</p>\r\n<p><img src=\"../../../assets/images-uploads/ZNeuj22q18tQpMq6hOrZ9gg3pMkS6QTFPKMNntkv.jpg\" alt=\"\" width=\"800\" height=\"600\" /></p>\r\n<p>ស្ថានីយទូរទស្សន៍ភីអិនអិន នឹងបន្តអញ្ជើញតារាល្បីៗ ជាច្រើនរូបទៀតរបស់ប្រទេសថៃ&nbsp;<strong>TV3&nbsp;</strong>និងតារាហុងកុង&nbsp;<strong>TVB&nbsp;</strong>ដើម្បីមកជួបផ្ទាល់ជាមួយប្រិយមិត្តអ្នកគាំទ្រនៅកម្ពុជា៕</p>', 1, '2021-10-16 08:34:04', '2021-10-16 08:34:04');
INSERT INTO `posts` VALUES (22, 'កម្មវិធី PNN SHOWCASE 2017', 1, 4, NULL, 'ថ្ងៃទី១៦ ខែតុលា ឆ្នាំ២០២១', NULL, NULL, NULL, 1, '10162021083834616a2d1ae19e8.jpg', '<p>ស្ថានីយទូរទស្សន៍PNN បានរៀបចំកម្មវិធី<strong>&nbsp;PNN SHOW CASE 2017</strong>&nbsp;ដើម្បីបង្ហាញជូនអំពីគម្រោងរៀបចំចាក់ផ្សាយ ក្នុងឆ្នាំ២០១៧។</p>\r\n<p><img src=\"../../../assets/images-uploads/d4ypeWxETPF0pVYLHPMu6TjPeQh2Yi3nuj6UyGOl.jpg\" alt=\"\" width=\"800\" height=\"450\" /></p>\r\n<p>បច្ចុប្បន្ននេះ ស្ថានីយទូរទស្សន៍ភីអិនអិន បាននិងកំពុងនាំយករឿងភាគ លំដាប់លេខមួយពីស្ថានីយទូរទស្សន៍&nbsp;<strong>TV3&nbsp;</strong>នៃប្រទេសថៃ ស្ថានីយទូរទស្សន៍&nbsp;<strong>TVB&nbsp;</strong>ហុងកុង ព្រមទាំងសហការជាមួយបណ្តាផលិតកម្មល្បីៗជាច្រើន ក្នុងប្រទេសកម្ពុជាក្នុងការផលិតរឿងភាគខ្មែរ។</p>\r\n<p><img src=\"../../../assets/images-uploads/ieXbjjfKxn8wxD7eDoqi9k4CKKFQF5rwbc9UMFfx.jpg\" alt=\"\" width=\"800\" height=\"533\" /></p>\r\n<p><img src=\"../../../assets/images-uploads/aUhVFPHHesXuGstX0C0LZdennjm2BLERJtKcR2Hw.jpg\" alt=\"\" width=\"800\" height=\"533\" /></p>\r\n<p>ក្នុងនោះដែរ កម្មវិធីព័ត៍មាន និងកម្មវិធីកម្សាន្តរបស់ភីអិនអិន សព្វថ្ងៃនេះក៏កំពុងតែមានសន្ទុះយ៉ាងខ្លាំង ដោយមានធនធានមនុស្ស ដែលប្រកបដោយវិជ្ជាជីរៈច្បាស់លាស់ ក្នុងការផលិតកម្មវិធី។</p>\r\n<p><img src=\"../../../assets/images-uploads/mZzfSvSTMU8zwgXNw2G8dhfx7dGM0obvQ9ZjlobK.jpg\" alt=\"\" width=\"800\" height=\"533\" /></p>\r\n<p><img src=\"../../../assets/images-uploads/fnbcSQmNURpDruTxa0dtYtCqnZvjtgo8ucWJtXX2.jpg\" alt=\"\" width=\"800\" height=\"533\" /></p>\r\n<p><img src=\"../../../assets/images-uploads/iWUgzvm4zWiVS4fGLRDHRemWxcwX8RsJ7KvnrrhA.jpg\" alt=\"\" width=\"800\" height=\"533\" /></p>\r\n<p><img src=\"../../../assets/images-uploads/bDMposx2yLUYA89N8HUx36xUNV72wRgI2fPaYqrI.jpg\" alt=\"\" width=\"800\" height=\"533\" /></p>\r\n<p>ជាការពិត ស្ថានីយទូរទស្សន៍ភីអិនអិន ទើបតែដំណើរការបាន ជាងមួយឆ្នាំប៉ុណ្ណោះ ប៉ុន្តែសមិទ្ធិផលដែលទទួលបានគឺ ភីអិនអិន ក្លាយជាស្ថានីយទូរទស្សន៍ ដែលស្ថិតក្នុងលំដាប់ឈានមុខគេមួយ នៅប្រទេសកម្ពុជា ក្នុងវិស័យប្រព័ន្ធផ្សព្វផ្សាយ៕</p>', 1, '2021-10-16 08:38:34', '2021-10-16 08:38:34');

-- ----------------------------
-- Table structure for subcates
-- ----------------------------
DROP TABLE IF EXISTS `subcates`;
CREATE TABLE `subcates`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `subcate_en` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `subcate_kh` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` tinyint(1) NOT NULL,
  `status` tinyint(1) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

